import { motion } from "framer-motion";
import { VesselBadge } from "../vessel-ui/VesselBadge";
import { SketchCircle } from "../icons/SketchCircle";

const fadeInUp = {
  hidden: { opacity: 0, y: 16 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, ease: [0.22, 1, 0.36, 1] as const },
  },
};

export function WaitingForGuestsEmpty() {
  return (
    <motion.div
      initial="hidden"
      animate="visible"
      variants={{
        hidden: { opacity: 0 },
        visible: {
          opacity: 1,
          transition: { staggerChildren: 0.08, delayChildren: 0.05 },
        },
      }}
      className="relative flex flex-col items-center text-center px-6 py-10"
    >
      {/* People illustration ringed by the same hand-drawn
          SketchCircle used on the vault EmptyState and the landing
          page CTA, with the accent-tinted halo blur behind it.
          Keeps the empty-state language consistent across screens. */}
      <motion.div
        variants={fadeInUp}
        className="relative w-32 h-32 mb-6 flex items-center justify-center"
      >
        <div
          aria-hidden="true"
          className="absolute inset-0 rounded-full bg-vessel-accent/10 blur-2xl"
        />
        <SketchCircle className="absolute inset-0 w-full h-full text-vessel-accent/40" />
        <PeopleIllustration />
      </motion.div>

      <motion.div variants={fadeInUp}>
        <VesselBadge variant="accent" className="mb-4">
          Studio doors are open
        </VesselBadge>
      </motion.div>

      <motion.h4
        variants={fadeInUp}
        className="font-display text-2xl sm:text-3xl font-bold text-vessel-text-primary tracking-tight leading-[1.15] mb-3 max-w-md"
      >
        Waiting for guests…
      </motion.h4>

      <motion.p
        variants={fadeInUp}
        className="text-vessel-text-secondary text-base sm:text-lg max-w-[380px] leading-relaxed"
      >
        Share the invite link above. They'll appear here the moment they
        join.
      </motion.p>

      <motion.p
        variants={fadeInUp}
        className="text-xs text-vessel-text-muted mt-6"
      >
        ✓ Anyone with the link can join — no account needed
      </motion.p>
    </motion.div>
  );
}

